def list_tweets(account_id, source_type=None, author_handle=None, conversation_x_tweet_id=None, in_reply_to_x_tweet_id=None, posted_by_account_id=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0253000" if __import__("os").path.isdir("./environment_mix/0253000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, extra=None):
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                rid = "req_" + base64.b32encode(os.urandom(10)).decode("utf-8").rstrip("=")
                row = {
                    "id": rid,
                    "endpoint": "list_tweets",
                    "account_id": account_id,
                    "status": status,
                    "timestamp": now,
                    "latency_ms": int((time.time() - t0) * 1000)
                }
                if isinstance(extra, dict):
                    row.update(extra)
                logs.append(row)
                _save(fname, logs)
                return

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # validate
    if not isinstance(account_id, str) or not re.match(r"^xacc_[0-9A-HJKMNP-TV-Z]{10,}$", account_id or ""):
        _log("validation_error")
        return _err("VALIDATION_ERROR", "account_id is invalid.")
    if source_type is not None and source_type not in ("searched", "fetched", "posted"):
        _log("validation_error")
        return _err("VALIDATION_ERROR", "source_type is invalid.")
    if posted_by_account_id is not None:
        if not isinstance(posted_by_account_id, str) or not re.match(r"^xacc_[0-9A-HJKMNP-TV-Z]{10,}$", posted_by_account_id):
            _log("validation_error")
            return _err("VALIDATION_ERROR", "posted_by_account_id is invalid.")
    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        _log("validation_error")
        return _err("VALIDATION_ERROR", "page_size must be between 1 and 200.")
    if page_token is not None and not isinstance(page_token, str):
        _log("validation_error")
        return _err("VALIDATION_ERROR", "page_token must be a string if provided.")

    accounts = _load("x_accounts.json")
    if not any(a.get("id") == account_id for a in accounts):
        _log("unauthorized")
        return _err("UNAUTHORIZED", "Account is not accessible.")

    offset = 0
    if page_token:
        if not page_token.startswith("o:"):
            _log("validation_error")
            return _err("VALIDATION_ERROR", "page_token is malformed.")
        try:
            offset = int(page_token.split(":", 1)[1])
            if offset < 0:
                raise ValueError()
        except Exception:
            _log("validation_error")
            return _err("VALIDATION_ERROR", "page_token is malformed.")

    tweets = _load("tweets.json")
    rows = tweets

    # filters
    if source_type is not None:
        rows = [r for r in rows if r.get("source_type") == source_type]
    if author_handle is not None:
        if not isinstance(author_handle, str):
            _log("validation_error")
            return _err("VALIDATION_ERROR", "author_handle must be a string.")
        ah = author_handle.lower()
        rows = [r for r in rows if isinstance(r.get("author_handle"), str) and r.get("author_handle").lower() == ah]
    if conversation_x_tweet_id is not None:
        if not isinstance(conversation_x_tweet_id, str):
            _log("validation_error")
            return _err("VALIDATION_ERROR", "conversation_x_tweet_id must be a string.")
        rows = [r for r in rows if r.get("conversation_x_tweet_id") == conversation_x_tweet_id]
    if in_reply_to_x_tweet_id is not None:
        if not isinstance(in_reply_to_x_tweet_id, str):
            _log("validation_error")
            return _err("VALIDATION_ERROR", "in_reply_to_x_tweet_id must be a string.")
        rows = [r for r in rows if r.get("in_reply_to_x_tweet_id") == in_reply_to_x_tweet_id]
    if posted_by_account_id is not None:
        rows = [r for r in rows if r.get("posted_by_account_id") == posted_by_account_id]

    # sort by observed_at desc, fallback to x_created_at, created_at
    def _sort_key(r):
        for f in ("observed_at", "x_created_at", "created_at", "updated_at"):
            dt = _parse_dt(r.get(f))
            if dt is not None:
                return dt
        return datetime.datetime(1970, 1, 1)

    rows.sort(key=_sort_key, reverse=True)

    total = len(rows)
    page = rows[offset: offset + page_size]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_token = f"o:{next_offset}" if has_more else None

    _log("ok", extra={"returned": len(page), "total": total})
    return {
        "tweets": page,
        "page": {
            "total": total,
            "count": len(page),
            "has_more": has_more,
            "next_page_token": next_token
        }
    }

