def update_outbound_post(account_id, outbound_post_id, status=None, body_text=None, media=None, **_extra):
    import json, os, datetime, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0253000" if __import__("os").path.isdir("./environment_mix/0253000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _b32_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return f"{prefix}_{''.join(random.choice(alphabet) for _ in range(16))}"

    def _log(status_code, used_account_id, error=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _b32_id("rlog"),
            "endpoint": "update_outbound_post",
            "account_id": used_account_id,
            "status": status_code,
            "error_code": (error or {}).get("code") if isinstance(error, dict) else None,
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            "timestamp": now,
            "created_at": now,
        }
        if isinstance(meta, dict):
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _within_last_24h(ts):
        dt = _parse_dt(ts)
        if dt is None:
            return False
        return dt >= (now_dt - datetime.timedelta(hours=24))

    def _media_is_acceptable_image(m):
        if m is None:
            return True, None
        if not isinstance(m, dict):
            return False, "media must be an object."
        if len(m) == 0:
            return True, None

        provider_id = m.get("provider_media_id")
        if provider_id is not None:
            if not isinstance(provider_id, str) or not provider_id.strip():
                return False, "media.provider_media_id must be a non-empty string when provided."
            return True, None

        url = m.get("url") or m.get("image_url")
        mime = m.get("mime_type")

        if url is None:
            return False, "media must include either provider_media_id or url/image_url."
        if not isinstance(url, str) or not url.strip():
            return False, "media.url/image_url must be a non-empty string when provided."

        if mime is None:
            return True, None
        if not isinstance(mime, str):
            return False, "media.mime_type must be a string when provided."
        mime_l = mime.strip().lower()
        if not mime_l.startswith("image/"):
            return False, "media must be an image payload (mime_type must start with 'image/')."
        allowed = {"image/jpeg", "image/jpg", "image/png", "image/gif", "image/webp"}
        if mime_l in allowed:
            return True, None
        if mime_l.startswith("image/"):
            return True, None
        return False, "media mime_type is not accepted."

    # ---- Validate inputs (schema) ----
    if not isinstance(account_id, str) or not re.match(r"^xacc_[0-9A-HJKMNP-TV-Z]{10,}$", account_id):
        err = _err("VALIDATION_ERROR", "account_id must be a string matching ^xacc_[0-9A-HJKMNP-TV-Z]{10,}$.")
        _log("error", account_id, err)
        return err

    # NOTE: Do not hard-fail on pattern mismatch; some callers may pass wrong id by mistake.
    # We'll still validate type and then attempt lookup; if not found -> NOT_FOUND.
    if not isinstance(outbound_post_id, str) or not outbound_post_id.strip():
        err = _err("VALIDATION_ERROR", "outbound_post_id must be a non-empty string.")
        _log("error", account_id, err)
        return err

    allowed_status = {"draft", "queued", "cancelled"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            err = _err("VALIDATION_ERROR", "status must be one of: draft, queued, cancelled.")
            _log("error", account_id, err)
            return err

    if body_text is not None and not isinstance(body_text, str):
        err = _err("VALIDATION_ERROR", "body_text must be a string when provided.")
        _log("error", account_id, err)
        return err
    if body_text is not None:
        if len(body_text) < 1 or len(body_text) > 280:
            err = _err("VALIDATION_ERROR", "body_text length must be between 1 and 280 characters for X.")
            _log("error", account_id, err)
            return err

    ok_media, media_err = _media_is_acceptable_image(media)
    if not ok_media:
        err = _err("VALIDATION_ERROR", media_err)
        _log("error", account_id, err)
        return err

    # ---- Load stores ----
    accounts = _load("x_accounts.json")
    posts = _load("outbound_posts.json")

    if not isinstance(accounts, list):
        accounts = []
    if not isinstance(posts, list):
        posts = []

    # ---- Ambient auth: request is authenticated; ensure account exists or find accessible combination ----
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id), None)
    if acct is None:
        # As per contract: only UNAUTHORIZED if no combination can serve. Here the request is scoped to account_id.
        err = _err("NOT_FOUND", "X account not found.", account_id=account_id)
        _log("error", account_id, err)
        return err

    # ---- Rate limit / quota enforcement (observable dynamics) ----
    # Enforce a rolling 24h quota for successful published outbound posts vs account.daily_post_limit.
    daily_post_limit = acct.get("daily_post_limit")
    if not isinstance(daily_post_limit, int) or daily_post_limit < 0:
        daily_post_limit = 0

    published_last_24h = 0
    for p in posts:
        if not isinstance(p, dict):
            continue
        if p.get("account_id") != account_id:
            continue
        if p.get("status") != "published":
            continue
        if _within_last_24h(p.get("published_at") or p.get("updated_at") or p.get("created_at")):
            published_last_24h += 1

    # Only enforce when the requested action could move into queued (i.e., a step toward publishing).
    # Editing drafts/cancelling doesn't consume quota.
    if status == "queued" and published_last_24h >= daily_post_limit:
        err = _err(
            "QUOTA_EXCEEDED",
            "Daily post limit exceeded for this account (rolling 24h window).",
            daily_post_limit=daily_post_limit,
            published_last_24h=published_last_24h,
        )
        _log("error", account_id, err)
        return err

    # ---- Locate outbound post (do not report success without effect) ----
    post = next((p for p in posts if isinstance(p, dict) and p.get("id") == outbound_post_id), None)
    if post is None:
        err = _err("NOT_FOUND", "Outbound post not found.", outbound_post_id=outbound_post_id)
        _log("error", account_id, err)
        return err

    # Ensure it belongs to the account in path (authorization check)
    if post.get("account_id") != account_id:
        err = _err("UNAUTHORIZED", "Outbound post does not belong to the specified account.", outbound_post_id=outbound_post_id)
        _log("error", account_id, err)
        return err

    # ---- Business rules: editable fields only while status is draft ----
    cur_status = post.get("status")
    if not isinstance(cur_status, str) or cur_status not in {"draft", "queued", "sending", "published", "failed", "cancelled"}:
        err = _err("VALIDATION_ERROR", "Outbound post has an invalid stored status.", status=cur_status)
        _log("error", account_id, err)
        return err

    if (body_text is not None or media is not None) and cur_status != "draft":
        err = _err(
            "INVALID_TRANSITION",
            "body_text/media may only be edited while the outbound post is in 'draft' status.",
            current_status=cur_status,
        )
        _log("error", account_id, err)
        return err

    # ---- Lifecycle transitions (caller can only set draft/queued/cancelled) ----
    transitions = {
        "draft": {"queued", "cancelled"},
        "queued": {"cancelled"},
        "sending": set(),     # provider-driven
        "published": set(),   # terminal
        "failed": {"queued", "cancelled"},
        "cancelled": set(),
    }

    # Idempotency: setting same status is OK (no transition), but must still potentially apply draft edits.
    if status is not None and status != cur_status:
        allowed = transitions.get(cur_status, set())
        if status not in allowed:
            err = _err(
                "INVALID_TRANSITION",
                "Invalid status transition for outbound post.",
                current_status=cur_status,
                requested_status=status,
                allowed_transitions=sorted(list(allowed)),
            )
            _log("error", account_id, err)
            return err

    # If moving to queued, enforce account is connected & posting_enabled before we ever reach sending.
    # (This endpoint doesn't set sending; but queueing is a step toward publish, so validate here.)
    if status == "queued" and status != cur_status:
        posting_enabled = acct.get("posting_enabled")
        # datastore may contain "True"/"False" strings; normalize
        if isinstance(posting_enabled, str):
            posting_enabled_norm = posting_enabled.strip().lower() == "true"
        else:
            posting_enabled_norm = bool(posting_enabled)

        if acct.get("auth_status") != "connected" or not posting_enabled_norm:
            # Allowed to record audit as failed update rather than silently accept.
            err = _err(
                "UNAUTHORIZED",
                "Account is not allowed to publish: auth_status must be 'connected' and posting_enabled must be true.",
                auth_status=acct.get("auth_status"),
                posting_enabled=posting_enabled_norm,
            )
            _log("error", account_id, err)
            return err

    # ---- Apply updates ----
    changed = False
    if body_text is not None and body_text != post.get("body_text"):
        post["body_text"] = body_text
        changed = True
    if media is not None:
        # Store as provided (including {}), since caller intent matters
        if media != post.get("media"):
            post["media"] = media
            changed = True

    if status is not None and status != cur_status:
        post["status"] = status
        changed = True
        # timestamps for lifecycle
        if status == "cancelled":
            # no explicit cancelled_at field in schema; rely on updated_at
            pass

    if not changed:
        # Real services typically return the row (idempotent) without error.
        post["updated_at"] = now  # still "observably touched"? avoid; but mutation without effect shouldn't claim.
        # However writing updated_at on no-op can be considered an effect. We'll avoid mutating if no changes.
        resp = {"outbound_post": post}
        _log("ok", account_id, None, {"no_op": True})
        return resp

    post["updated_at"] = now

    # ---- Persist ----
    # Write back into list (post is already referencing dict in list, but keep deterministic)
    for i, p in enumerate(posts):
        if isinstance(p, dict) and p.get("id") == outbound_post_id:
            posts[i] = post
            break
    _save("outbound_posts.json", posts)

    resp = {"outbound_post": post}
    _log("ok", account_id, None)
    return resp

def list_reply_generations(account_id, status=None, mode=None, target_tweet_id=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0253000" if __import__("os").path.isdir("./environment_mix/0253000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

