    def _log(status_code, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "rlog_" + base64.b32encode(os.urandom(10)).decode("utf-8").rstrip("="),
                "endpoint": "list_reply_generations",
                "account_id": account_id,
                "status": status_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now,
                "meta": meta or {},
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    # Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^xacc_[0-9A-HJKMNP-TV-Z]{10,}$", account_id):
        _log("VALIDATION_ERROR", {"field": "account_id"})
        return _err("VALIDATION_ERROR", "Invalid account_id.")

    if status is not None:
        if not isinstance(status, str) or status not in ("queued", "running", "succeeded", "failed", "cancelled"):
            _log("VALIDATION_ERROR", {"field": "status"})
            return _err("VALIDATION_ERROR", "Invalid status filter.")
    if mode is not None:
        if not isinstance(mode, str) or mode not in ("to_tweet", "to_message"):
            _log("VALIDATION_ERROR", {"field": "mode"})
            return _err("VALIDATION_ERROR", "Invalid mode filter.")
    if target_tweet_id is not None:
        if not isinstance(target_tweet_id, str) or not re.match(r"^twt_[0-9A-HJKMNP-TV-Z]{10,}$", target_tweet_id):
            _log("VALIDATION_ERROR", {"field": "target_tweet_id"})
            return _err("VALIDATION_ERROR", "Invalid target_tweet_id.")
    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        _log("VALIDATION_ERROR", {"field": "page_size"})
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200.")
    if page_token is not None and not isinstance(page_token, str):
        _log("VALIDATION_ERROR", {"field": "page_token"})
        return _err("VALIDATION_ERROR", "page_token must be a string.")

    # Ambient auth: if account exists, it's accessible
    accounts = _load("x_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id), None)
    if not acct:
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Account not accessible.")

    gens = _load("reply_generations.json")
    if not isinstance(gens, list):
        gens = []

    # Filter
    rows = []
    for g in gens:
        if not isinstance(g, dict):
            continue
        if g.get("account_id") != account_id:
            continue
        if status is not None and g.get("status") != status:
            continue
        if mode is not None and g.get("mode") != mode:
            continue
        if target_tweet_id is not None and g.get("target_tweet_id") != target_tweet_id:
            continue
        rows.append(g)

    def _created_key(r):
        ca = r.get("created_at")
        # sort desc; None last
        return ca if isinstance(ca, str) else ""

    # Order by created_at desc, tie-breaker id desc for stable pagination
    rows.sort(key=lambda r: (_created_key(r), r.get("id", "")), reverse=True)

    # Pagination: page_token is opaque; we encode last_seen created_at + id
    start = 0
    if page_token:
        try:
            raw = base64.urlsafe_b64decode(page_token.encode("utf-8") + b"===").decode("utf-8")
            parts = raw.split("|", 2)
            if len(parts) == 2:
                last_created, last_id = parts
                # find first row strictly after the cursor in our ordering (desc)
                for i, r in enumerate(rows):
                    ck = _created_key(r)
                    rid = r.get("id", "")
                    if (ck, rid) == (last_created, last_id):
                        start = i + 1
                        break
        except Exception:
            _log("VALIDATION_ERROR", {"field": "page_token"})
            return _err("VALIDATION_ERROR", "Invalid page_token.")

    page = rows[start:start + page_size]
    has_more = (start + page_size) < len(rows)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        payload = f"{_created_key(last)}|{last.get('id','')}"
        next_cursor = base64.urlsafe_b64encode(payload.encode("utf-8")).decode("utf-8").rstrip("=")

    _log("OK", {"returned": len(page), "total": len(rows)})
    return {
        "reply_generations": page,
        "pagination": {
            "total": len(rows),
            "page_size": page_size,
            "has_more": has_more,
            "next_page_token": next_cursor
        }
    }

def get_auth_context(account_id=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0253000" if __import__("os").path.isdir("./environment_mix/0253000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "rlog_" + base64.b32encode(os.urandom(10)).decode("utf-8").rstrip("="),
                "endpoint": "get_auth_context",
                "account_id": account_id,
                "status": status_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now,
                "meta": meta or {},
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    if account_id is not None:
        if not isinstance(account_id, str) or not re.match(r"^xacc_[0-9A-HJKMNP-TV-Z]{10,}$", account_id):
            _log("VALIDATION_ERROR", {"field": "account_id"})
            return _err("VALIDATION_ERROR", "Invalid account_id.")

    accounts = _load("x_accounts.json")
    if not isinstance(accounts, list):
        accounts = []

    # Ambient auth: if there is at least one account, the caller has access to some identity.
    # If the caller scopes to account_id, require it exist.
    if account_id is not None:
        scoped = [a for a in accounts if isinstance(a, dict) and a.get("id") == account_id]
        if not scoped:
            _log("UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Invalid or expired credentials for requested account scope.")
        accessible = scoped
    else:
        if len([a for a in accounts if isinstance(a, dict) and a.get("id")]) == 0:
            _log("UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Invalid or expired credentials.")
        accessible = [a for a in accounts if isinstance(a, dict)]

    # Compute quota usage in last 24h window (implementation-defined per rules)
    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    cutoff = datetime.datetime.utcnow().replace(microsecond=0) - datetime.timedelta(hours=24)

    outbound = _load("outbound_posts.json")
    if not isinstance(outbound, list):
        outbound = []
    searches = _load("search_queries.json")
    if not isinstance(searches, list):
        searches = []
    gens = _load("reply_generations.json")
    if not isinstance(gens, list):
        gens = []

    def _account_usage(aid):
        # posts: successful published in last 24h by published_at (fallback updated_at)
        pub = 0
        for p in outbound:
            if not isinstance(p, dict) or p.get("account_id") != aid:
                continue
            if p.get("status") != "published":
                continue
            dt = _parse_dt(p.get("published_at")) or _parse_dt(p.get("updated_at")) or _parse_dt(p.get("created_at"))
            if dt and dt >= cutoff:
                pub += 1

        # searches: executions in last 24h by created_at
        sch = 0
        for q in searches:
            if not isinstance(q, dict) or q.get("account_id") != aid:
                continue
            dt = _parse_dt(q.get("created_at")) or _parse_dt(q.get("updated_at"))
            if dt and dt >= cutoff:
                sch += 1

        # ai replies: succeeded in last 24h by updated_at (or created_at)
        suc = 0
        for g in gens:
            if not isinstance(g, dict) or g.get("account_id") != aid:
                continue
            if g.get("status") != "succeeded":
                continue
            dt = _parse_dt(g.get("updated_at")) or _parse_dt(g.get("created_at"))
            if dt and dt >= cutoff:
                suc += 1

        return pub, sch, suc

    # Report per account quotas
    accessible_slim = []
    quota_report = {}
    for a in accessible:
        aid = a.get("id")
        if not isinstance(aid, str):
            continue
        pub, sch, suc = _account_usage(aid)
        lim_post = a.get("daily_post_limit")
        lim_search = a.get("daily_search_limit")
        lim_ai = a.get("daily_ai_reply_limit")

        quota_report[aid] = {
            "window": "rolling_24h",
            "posts": {"used": pub, "limit": lim_post},
            "searches": {"used": sch, "limit": lim_search},
            "ai_replies": {"used": suc, "limit": lim_ai},
        }

        accessible_slim.append({
            "id": aid,
            "handle": a.get("handle"),
            "x_user_id": a.get("x_user_id"),
            "display_name": a.get("display_name"),
            "auth_status": a.get("auth_status"),
            "posting_enabled": a.get("posting_enabled"),
            "default_language": a.get("default_language"),
            "created_at": a.get("created_at"),
            "updated_at": a.get("updated_at"),
        })

    # Scopes: schema doesn't define; infer basic allowed operations based on auth_status/posting_enabled
    def _scopes_for(a):
        scopes = ["read:tweets", "read:searches", "read:reply_generations"]
        if a.get("auth_status") == "connected" and a.get("posting_enabled") is True:
            scopes.append("write:posts")
        if a.get("auth_status") == "connected":
            scopes.append("write:reply_generation")
            scopes.append("write:search")
        return scopes

    scopes = {}
    for a in accessible:
        aid = a.get("id")
        if isinstance(aid, str):
            scopes[aid] = _scopes_for(a)

    _log("OK", {"accounts": len(accessible_slim)})
    return {
        "identity": {
            "type": "ambient",
            "authenticated": True,
        },
        "accounts": accessible_slim,
        "scopes": scopes,
        "quota": quota_report,
        "rate_limit": {
            "enforced": False,
            "note": "No rate-limit collection configured in datastore; only quotas are reported."
        }
    }
